"""Original Indonesian teaching content. Run from the repository root."""
import json
from pathlib import Path

LESSONS = []

def example(value):
    jp, kana, meaning = value.split('|')
    return dict(japanese=jp, reading=kana, meaning=meaning)

def point(pattern, meaning, formation, explanation, mistake, first, second, blank, choices, feedback):
    return dict(pattern=pattern, meaning=meaning, formation=formation,
                explanation=explanation, commonMistake=mistake,
                examples=[example(first), example(second)],
                practice=dict(prompt=blank, choices=choices.split('|'), correct=0, explanation=feedback))

def lesson(chapter, title, a, b):
    LESSONS.append(dict(chapter=chapter, title=title, points=[a, b]))

lesson('Waktu dan kesempatan', 'Selagi keadaan masih berlangsung',
point('～うちに', 'selagi …; sebelum keadaan berubah', 'V辞書形／Vない形／Vている + うちに; Aい + うちに; Aな + なうちに; N + のうちに', 'Kesempatan melakukan tindakan dibatasi keadaan yang masih berlangsung. Bagian akhir biasanya tindakan yang ingin diselesaikan sebelum keadaan berubah. Dibanding 間に, うちに menekankan kesempatan yang dapat hilang.', 'Kata benda memakai の, sifat な memakai な. Jangan menyamakan ないうちに dengan setelah tindakan selesai.', '温かいうちに食べてください。|あたたかい うちに たべてください。|Silakan makan selagi masih hangat.', '忘れないうちにメモしておきます。|わすれない うちに メモしておきます。|Saya akan mencatatnya sebelum lupa.', 'Silakan makan sebelum makanan dingin: 温かい（　）食べてください。', 'うちに|のうちに|なうちに|うちを', '温かい merupakan sifat い, langsung diikuti うちに. Kesempatan makan hangat akan hilang ketika dingin.'),
point('～ているうちに', 'selama melakukan …, perlahan terjadi perubahan', 'Vている + うちに', 'Menunjukkan perubahan yang muncul selama suatu proses, sering tanpa direncanakan. Subjek mulai memahami, terbiasa, atau berubah perasaan setelah kegiatan berlangsung.', 'Dalam makna perubahan alami ini, bagian akhir bukan selalu tindakan sengaja untuk memanfaatkan kesempatan.', '毎日話しているうちに、日本語に慣れました。|まいにち はなしている うちに、にほんごに なれました。|Selama berbicara setiap hari, saya menjadi terbiasa dengan bahasa Jepang.', '本を読んでいるうちに、眠くなりました。|ほんを よんでいる うちに、ねむく なりました。|Ketika terus membaca buku, saya menjadi mengantuk.', '変化が少しずつ起きました: 毎日話している（　）、日本語に慣れました。', 'うちに|前に|までに|ためだけに', 'Berbicara terjadi lebih dahulu sebagai proses; menjadi terbiasa berkembang selama proses itu. 前に justru berarti sebelum.'))

lesson('Waktu dan kesempatan', 'Rentang waktu dan kejadian di dalamnya',
point('～間／～間に', 'selama seluruh rentang / pada suatu saat dalam rentang', 'Vている／V辞書形 + 間（に）; Aい + 間（に）; Aな + な間（に）; N + の間（に）', '間 menunjukkan kegiatan yang berlangsung sepanjang rentang, sedangkan 間に menempatkan suatu kejadian di dalam rentang tersebut. Fokusnya rentang waktu, bukan kesempatan yang akan hilang seperti うちに.', 'Jangan memakai 間 untuk satu kejadian singkat jika maksudnya terjadi sekali saat rentang berlangsung; gunakan 間に.', '夏休みの間、図書館で働きました。|なつやすみの あいだ、としょかんで はたらきました。|Saya bekerja di perpustakaan selama liburan musim panas.', '留守の間に、荷物が届きました。|るすの あいだに、にもつが とどきました。|Paket tiba ketika saya sedang tidak di rumah.', 'Paket tiba sekali saat rumah kosong: 留守の（　）、荷物が届きました。', '間に|間を|間で|間から', 'Kejadian tiba terjadi pada suatu saat di dalam waktu rumah kosong: 間に.'),
point('～最中に', 'tepat ketika sedang di tengah …', 'Vている + 最中に; N + の最中に', 'Menekankan kegiatan sedang berjalan di tengah proses. Sering diikuti kejadian yang menyela atau mengejutkan, tetapi gangguan bukan syarat mutlak.', '最中 dibaca さいちゅう. Kata kerja belum mulai tidak memakai 辞書形＋最中 dalam pola ini.', '会議の最中に、電話が鳴りました。|かいぎの さいちゅうに、でんわが なりました。|Telepon berbunyi tepat di tengah rapat.', '料理している最中に、友達が来ました。|りょうりしている さいちゅうに、ともだちが きました。|Teman datang ketika saya sedang memasak.', '会議（　）最中に、電話が鳴りました。', 'の|な|を|と', '会議 merupakan kata benda dan dihubungkan dengan の sebelum 最中に.'))

lesson('Waktu dan kesempatan', 'Syarat urutan dan waktu mendadak',
point('～てからでないと', 'jika belum selesai …, tidak bisa …', 'Vて + からでないと + hasil negatif', 'Tindakan pertama harus selesai sebelum tindakan kedua mungkin atau diizinkan. Akhir kalimat umumnya negatif, seperti できない atau 分からない. Bentuk tertulis terkait: てからでなければ.', 'Berbeda dari てから biasa, pola ini menegaskan prasyarat dan lazim diikuti hasil negatif.', '予約してからでないと、入れません。|よやくしてからでないと、はいれません。|Anda tidak bisa masuk sebelum membuat reservasi.', '実物を見てからでないと、決められません。|じつぶつを みてからでないと、きめられません。|Saya tidak bisa memutuskan sebelum melihat barang aslinya.', '予約（　）、入れません。 Pilih prasyarat yang harus selesai dulu.', 'してからでないと|するうちに|した最中に|している間ずっと', 'してからでないと menegaskan reservasi harus dilakukan sebelum masuk bisa dilakukan.'),
point('～たとたん（に）', 'begitu …, langsung terjadi …', 'Vた + とたん（に）', 'Dua kejadian terjadi berdekatan; kejadian kedua sering mendadak dan tidak diduga. Digunakan untuk laporan kejadian, bukan permintaan atau rencana yang sengaja dilakukan.', 'Untuk instruksi seperti “setelah pulang, teleponlah”, gunakan たら atau てから, bukan たとたん.', '窓を開けたとたん、風が入ってきました。|まどを あけた とたん、かぜが はいってきました。|Begitu jendela dibuka, angin langsung masuk.', '立ち上がったとたんに、めまいがしました。|たちあがった とたんに、めまいが しました。|Begitu berdiri, saya langsung merasa pusing.', 'Begitu jendela dibuka, angin mendadak masuk: 窓を（　）とたん、風が入ってきました。', '開けた|開ける|開けて|開けない', 'とたん mengikuti bentuk lampau た: 開けたとたん.'))

lesson('Waktu dan kesempatan', 'Setiap kejadian dan sambil sekalian',
point('～たびに', 'setiap kali …', 'V辞書形 + たびに; N + のたびに', 'Menghubungkan kejadian berulang dengan hasil yang muncul setiap kali. Tidak hanya satu pengalaman; pola ini menyatakan pengulangan yang diamati pembicara.', 'たびに bukan penanda satu kejadian lampau. Kata benda memerlukan の.', 'この写真を見るたびに、旅行を思い出します。|この しゃしんを みる たびに、りょこうを おもいだします。|Setiap melihat foto ini, saya teringat perjalanan itu.', '出張のたびに、お土産を買います。|しゅっちょうの たびに、おみやげを かいます。|Setiap perjalanan dinas, saya membeli oleh-oleh.', '出張（　）たびに、お土産を買います。', 'の|な|に|を', '出張 adalah kata benda: 出張のたびに.'),
point('～ついでに', 'sekalian saat melakukan …', 'V辞書形／Vた + ついでに; N + のついでに', 'Tindakan pertama merupakan tujuan utama. Tindakan kedua dilakukan sebagai tambahan karena kesempatan yang sama, sering lebih ringan atau berkaitan tempat.', 'Berbeda dari ながら, dua kegiatan tidak harus dilakukan pada saat yang persis sama.', '買い物に行くついでに、郵便局に寄ります。|かいものに いく ついでに、ゆうびんきょくに よります。|Saya akan mampir ke kantor pos sekalian pergi belanja.', '部屋を掃除したついでに、窓も拭きました。|へやを そうじした ついでに、まども ふきました。|Sekalian membersihkan kamar, saya juga mengelap jendela.', 'Tujuan utama belanja, tambahan mampir: 買い物に行く（　）、郵便局に寄ります。', 'ついでに|とたんに|最中だけ|せいで', 'ついでに menyatakan kesempatan kegiatan utama dipakai untuk kegiatan tambahan.'))

lesson('Tahap dan hasil kegiatan', 'Hampir terjadi dan temuan setelah mencoba',
point('～ところだった', 'hampir …, tetapi akhirnya tidak terjadi', 'V辞書形 + ところだった', 'Konteks masa lampau menunjukkan tindakan atau kejadian hampir terjadi. Sering dipakai saat merasa lega atau menyesal karena sesuatu nyaris terjadi; あやうく dapat memperjelas makna hampir.', 'ところです berarti baru hendak melakukan; makna “nyaris” pada ところだった perlu konteks yang menunjukkan hasil tidak terjadi.', 'あやうく電車に乗り遅れるところでした。|あやうく でんしゃに のりおくれる ところでした。|Saya hampir ketinggalan kereta.', '財布を忘れるところでしたが、友達が教えてくれました。|さいふを わすれる ところでしたが、ともだちが おしえてくれました。|Saya nyaris meninggalkan dompet, tetapi teman mengingatkan saya.', 'Saya hampir ketinggalan, tetapi sempat naik: あやうく電車に（　）ところでした。', '乗り遅れる|乗り遅れた|乗り遅れて|乗り遅れます', 'Makna nyaris memakai V辞書形＋ところだった. 乗り遅れたところ justru menunjuk tahap sesudah ketinggalan.'),
point('～たところ', 'setelah mencoba …, ternyata …', 'Vた + ところ + hasil atau temuan', 'Melaporkan hasil atau informasi yang ditemukan setelah melakukan tindakan. Berbeda dari たところです yang menunjukkan baru saja selesai; di sini ところ menghubungkan tindakan dengan hasil.', 'Jangan menganggap semua たところ berarti “baru saja”. Perhatikan klausa hasil yang mengikutinya.', '店に電話したところ、今日は休みだと分かりました。|みせに でんわした ところ、きょうは やすみだと わかりました。|Setelah menelepon toko, ternyata hari ini toko tutup.', '先生に聞いたところ、締め切りは金曜日でした。|せんせいに きいた ところ、しめきりは きんようびでした。|Setelah bertanya kepada guru, ternyata tenggatnya hari Jumat.', '店に（　）ところ、今日は休みだと分かりました。', '電話した|電話する|電話して|電話しない', 'Temuan diperoleh setelah menelepon: 電話したところ.'))

lesson('Tahap dan hasil kegiatan', 'Sejak suatu kejadian dan kegiatan terus-menerus',
point('～て以来', 'sejak … hingga sekarang', 'Vて + 以来; N peristiwa + 以来', 'Suatu peristiwa menjadi titik awal keadaan atau kebiasaan yang berlanjut sampai waktu yang dibicarakan. Umumnya memerlukan rentang yang cukup berarti, bukan baru beberapa saat.', 'Akibat sesaat tidak cocok dengan makna kesinambungan 以来. Untuk urutan singkat cukup てから.', '日本に来て以来、毎日日本語を使っています。|にほんに きていらい、まいにち にほんごを つかっています。|Sejak datang ke Jepang, saya memakai bahasa Jepang setiap hari.', '卒業以来、彼に会っていません。|そつぎょういらい、かれに あっていません。|Sejak lulus, saya belum pernah bertemu dengannya.', '日本に（　）以来、毎日日本語を使っています。', '来て|来た|来る|来ない', 'Bentuk て menghubungkan titik awal dengan 以来: 来て以来.'),
point('～てばかりいる', 'terus saja melakukan …', 'Vて + ばかりいる', 'Menyatakan satu jenis kegiatan mendominasi, sering dengan penilaian bahwa pelaku sebaiknya melakukan hal lain. Bentuk sopannya てばかりいます.', 'Jangan tertukar dengan たばかり, yang berarti baru saja selesai.', '弟はゲームをしてばかりいます。|おとうとは ゲームを してばかりいます。|Adik laki-laki saya terus saja bermain gim.', '文句を言ってばかりいないで、手伝ってください。|もんくを いってばかりいないで、てつだってください。|Jangan terus mengeluh; tolong bantu.', '弟はゲームを（　）ばかりいます。', 'して|した|する|しない', 'Kegiatan yang terus mendominasi memakai bentuk て: してばかりいる.'))

lesson('Keputusan dan usaha', 'Kebiasaan yang diputuskan dan instruksi tidak langsung',
point('～ことにしている', 'menetapkan kebiasaan untuk …', 'V辞書形／Vない形 + ことにしている', 'Keputusan pribadi telah dijadikan aturan atau kebiasaan yang dipertahankan. Berbeda dari ことにした yang berfokus pada saat keputusan dibuat.', 'ことになっている lazim menyatakan aturan atau pengaturan dari luar, bukan kebiasaan pilihan pribadi.', '毎朝三十分歩くことにしています。|まいあさ さんじゅっぷん あるくことに しています。|Saya menetapkan kebiasaan berjalan tiga puluh menit setiap pagi.', '寝る前にスマホを見ないことにしています。|ねる まえに スマホを みないことに しています。|Saya membiasakan diri tidak melihat ponsel sebelum tidur.', 'Aturan pribadi yang dipertahankan: 毎朝歩く（　）しています。', 'ことに|ことを|ものに|ためを', 'ことにしている menyatakan keputusan pribadi yang terus dijalankan.'),
point('～ように言う', 'menyuruh atau mengingatkan agar …', 'V辞書形／Vない形 + ように + 言う／頼む／注意する', 'Menyampaikan isi instruksi secara tidak langsung. Pelaku perintah dan orang yang diminta melakukan tindakan dapat berbeda; penerima instruksi biasanya diikuti に.', 'Untuk melaporkan pernyataan informasi biasa gunakan と言う. ように言う berfokus pada instruksi.', '先生は学生に早く来るように言いました。|せんせいは がくせいに はやく くるように いいました。|Guru menyuruh murid datang lebih awal.', '母に無理をしないように言われました。|ははに むりを しないように いわれました。|Ibu mengingatkan saya agar tidak memaksakan diri.', 'Instruksi agar datang awal: 先生は早く来る（　）言いました。', 'ように|ことを|ためで|うちを', '来るように言う adalah laporan instruksi tidak langsung.'))

lesson('Keputusan dan usaha', 'Mencoba bertindak dan enggan bertindak',
point('～ようとする', 'berusaha atau baru hendak …', 'V意向形 + とする', 'Menunjukkan usaha memulai tindakan atau saat tepat sebelum memulai. Bentuk kehendak berbeda menurut kelompok: 読もう, 食べよう, しよう, 来よう.', 'Jangan memakai V辞書形＋とする untuk pola usaha ini. てみる berfokus mencoba pengalaman, bukan usaha memulai.', 'ドアを開けようとしましたが、開きませんでした。|ドアを あけようと しましたが、あきませんでした。|Saya mencoba membuka pintu, tetapi pintu tidak terbuka.', '出かけようとした時、電話が鳴りました。|でかけようと した とき、でんわが なりました。|Ketika saya baru hendak pergi, telepon berbunyi.', 'Saya mencoba membuka: ドアを（　）としました。', '開けよう|開ける|開けた|開けて', '意向形 dari 開ける adalah 開けよう: 開けようとする.'),
point('～ようとしない', 'tidak mau atau tidak berusaha …', 'V意向形 + としない', 'Menggambarkan keengganan atau tidak adanya usaha yang terlihat pada seseorang. Sering membicarakan orang lain berdasarkan perilakunya.', 'Tidak mau mencoba berbeda dari tidak bisa. Kemampuan yang tidak ada dinyatakan dengan bentuk potensial negatif.', '弟は野菜を食べようとしません。|おとうとは やさいを たべようと しません。|Adik laki-laki saya tidak mau makan sayuran.', '彼は理由を説明しようとしません。|かれは りゆうを せつめいしようと しません。|Dia tidak mau menjelaskan alasannya.', 'Enggan menjelaskan: 彼は理由を（　）としません。', '説明しよう|説明した|説明して|説明する', 'Keengganan memakai bentuk kehendak＋としない: 説明しようとしない.'))

lesson('Saran dan kewajiban', 'Tindakan yang seharusnya dilakukan',
point('～べきだ', 'seharusnya …; patut …', 'V辞書形 + べきだ; する dapat menjadi するべき／すべき', 'Penilaian kuat tentang tindakan yang benar atau tanggung jawab. Lebih tegas daripada たほうがいい, sehingga perlu berhati-hati saat memberi nasihat langsung kepada orang lain.', 'べき tidak cocok untuk memaksakan pilihan selera pribadi atau hal yang tidak dapat dikendalikan seperti cuaca.', '約束は守るべきです。|やくそくは まもるべきです。|Janji seharusnya ditepati.', '大切なことは自分で確認すべきです。|たいせつな ことは じぶんで かくにんすべきです。|Hal penting seharusnya diperiksa sendiri.', '約束は（　）べきです。', '守る|守った|守って|守らない', 'べき langsung mengikuti bentuk kamus: 守るべき.'),
point('～べきではない', 'seharusnya tidak …', 'V辞書形 + べきではない', 'Menilai tindakan sebagai tidak patut. Negasi ditempatkan setelah べき; kalimat tidak menyuruh melakukan tindakan negatif.', 'Untuk “tidak seharusnya berbohong” gunakan うそをつくべきではない. つかないべき bukan bentuk dasar yang diajarkan.', '人の秘密を話すべきではありません。|ひとの ひみつを はなすべきでは ありません。|Anda tidak seharusnya menceritakan rahasia orang lain.', '見た目だけで判断すべきではありません。|みためだけで はんだんすべきでは ありません。|Kita tidak seharusnya menilai hanya dari penampilan.', '人の秘密を話す（　）。 Pilih larangan berupa penilaian “tidak seharusnya”.', 'べきではありません|べきでした|べきになります|べきにします', 'Negasi penilaian べき adalah べきではない／べきではありません.'))

lesson('Saran dan kewajiban', 'Tidak perlu dan tidak punya pilihan',
point('～ことはない', 'tidak perlu …', 'V辞書形 + ことはない', 'Menenangkan atau memberi saran bahwa suatu tindakan tidak perlu dilakukan. Tidak menyatakan larangan dan bukan keterangan pengalaman.', 'Vたことがない berarti belum pernah, sedangkan V辞書形＋ことはない berarti tidak perlu dalam makna ini.', 'そんなに心配することはありません。|そんなに しんぱいすることは ありません。|Tidak perlu khawatir sampai seperti itu.', '急ぐことはないので、ゆっくり来てください。|いそぐことは ないので、ゆっくり きてください。|Tidak perlu terburu-buru, jadi datanglah dengan santai.', 'Tidak perlu khawatir: そんなに心配（　）ことはありません。', 'する|した|して|します', 'Nasihat tidak perlu memakai bentuk kamus: 心配することはない.'),
point('～しかない', 'tidak ada pilihan selain …', 'V辞書形 + しかない', 'Pembicara menilai pilihan lain tidak tersedia. Bisa bernuansa terpaksa atau keputusan praktis. Ini berbeda dari Nしかない yang membatasi jumlah benda.', 'Jangan memakai Vない＋しかない untuk arti “harus melakukan”; tindakan yang menjadi satu-satunya pilihan memakai bentuk kamus.', '終電がないので、タクシーで帰るしかありません。|しゅうでんが ないので、タクシーで かえるしか ありません。|Karena kereta terakhir sudah tidak ada, saya hanya bisa pulang naik taksi.', 'データが消えたので、最初から作り直すしかありません。|データが きえたので、さいしょから つくりなおすしか ありません。|Karena datanya hilang, tidak ada pilihan selain membuatnya ulang dari awal.', 'Kereta sudah tidak ada, satu-satunya pilihan taksi: タクシーで（　）しかありません。', '帰る|帰った|帰って|帰ります', '帰るしかない berarti tidak ada pilihan selain pulang dengan cara itu.'))

lesson('Saran dan kewajiban', 'Tidak bisa menghindari tanggung jawab',
point('～わけにはいかない', 'tidak bisa … karena tanggung jawab atau keadaan', 'V辞書形 + わけにはいかない', 'Kemampuan fisik mungkin ada, tetapi tanggung jawab, norma, janji, atau situasi menghalangi tindakan. Berbeda dari bentuk potensial negatif yang berfokus pada ketidakmampuan.', 'Pola ini tidak sekadar berarti tidak tahu cara atau tidak sanggup secara fisik.', '明日は試験なので、遊ぶわけにはいきません。|あしたは しけんなので、あそぶ わけには いきません。|Besok ada ujian, jadi saya tidak bisa bersantai bermain.', '約束したので、断るわけにはいきません。|やくそくしたので、ことわる わけには いきません。|Karena sudah berjanji, saya tidak bisa menolak.', 'Sudah berjanji sehingga tidak pantas menolak: 断る（　）。', 'わけにはいきません|ことはありません|たびにいます|最中です', 'わけにはいかない menyatakan kendala tanggung jawab meskipun menolak secara fisik mungkin dilakukan.'),
point('～ないわけにはいかない', 'tidak bisa tidak …; harus …', 'Vない形 + わけにはいかない', 'Negasi ganda berarti tidak dapat menghindari melakukan tindakan karena keadaan atau kewajiban sosial. Maknanya harus dilakukan, bukan dilarang melakukan.', 'Perhatikan ない pada kata kerja: 行くわけにはいかない berarti tidak bisa pergi; 行かないわけにはいかない berarti harus pergi.', '招待されたので、行かないわけにはいきません。|しょうたいされたので、いかない わけには いきません。|Karena sudah diundang, saya tidak bisa tidak hadir.', '私のミスなので、謝らないわけにはいきません。|わたしの ミスなので、あやまらない わけには いきません。|Karena ini kesalahan saya, saya harus meminta maaf.', 'Kesalahan sendiri, harus meminta maaf: （　）わけにはいきません。', '謝らない|謝る|謝った|謝って', '謝らないわけにはいかない berarti tidak bisa menghindari meminta maaf.'))

lesson('Alasan dan akibat', 'Penyebab yang menguntungkan dan merugikan',
point('～おかげで', 'berkat …', 'V普通形／Aい + おかげで; Aな + なおかげで; N + のおかげで', 'Menjelaskan penyebab hasil yang menguntungkan dengan rasa syukur. Kadang dipakai ironis, tetapi materi ini memakai makna positif dasar.', 'Kata benda memakai の; untuk hasil buruk yang disalahkan biasanya gunakan せいで.', '先生のおかげで、合格できました。|せんせいの おかげで、ごうかくできました。|Berkat guru, saya bisa lulus.', '道が空いていたおかげで、早く着きました。|みちが すいていた おかげで、はやく つきました。|Berkat jalan yang tidak ramai, saya tiba lebih awal.', '先生（　）おかげで、合格できました。', 'の|な|を|で', '先生 merupakan kata benda: 先生のおかげで.'),
point('～せいで／～せいだ', 'karena …; gara-gara …', 'V普通形／Aい + せいで; Aな + なせいで; N + のせいで', 'Mengaitkan hasil buruk dengan penyebab, sering mengandung penilaian atau menyalahkan. せいだ mengakhiri kalimat; せいで menghubungkan ke akibat.', 'せいで terdengar menyalahkan jika dipakai kepada orang. Untuk sebab netral gunakan ので atau ため.', '雨のせいで、試合が中止になりました。|あめの せいで、しあいが ちゅうしに なりました。|Gara-gara hujan, pertandingan dibatalkan.', '寝不足のせいで、集中できません。|ねぶそくの せいで、しゅうちゅうできません。|Karena kurang tidur, saya tidak bisa berkonsentrasi.', 'Akibat buruk karena hujan: 雨の（　）、試合が中止になりました。', 'せいで|おかげで|ついでに|たびだけ', 'せいで menghubungkan penyebab dengan hasil buruk. おかげで biasanya memberi penilaian positif.'))

lesson('Alasan dan akibat', 'Penyebab formal dan emosi berlebihan',
point('～ため（に）：原因', 'karena …; akibat …', 'V普通形／Aい + ため（に）; Aな + なため（に）; N + のため（に）', 'Melaporkan penyebab secara relatif formal dan objektif, sering dalam pengumuman. Bedakan dari makna tujuan: dalam sebab, klausa berikut melaporkan akibat, bukan tindakan untuk mencapai tujuan.', 'Nのために dan V辞書形＋ために dapat bermakna tujuan atau sebab. Tentukan berdasarkan konteks, jangan terjemahkan selalu “untuk”.', '大雪のため、電車が止まっています。|おおゆきの ため、でんしゃが とまっています。|Karena salju lebat, kereta sedang berhenti beroperasi.', '道が混んでいたため、到着が遅れました。|みちが こんでいた ため、とうちゃくが おくれました。|Karena jalan ramai, kedatangan terlambat.', 'Penyebab pengumuman: 大雪（　）ため、電車が止まっています。', 'の|な|を|と', '大雪 adalah kata benda: 大雪のため. Kereta berhenti merupakan akibat, bukan tujuan salju.'),
point('～あまり（に）', 'karena terlalu … sampai …', 'V辞書形／Vた + あまり; Aな + なあまり; N + のあまり', 'Keadaan atau emosi menjadi begitu kuat sehingga menyebabkan hasil yang biasanya tidak diharapkan. Bentuk あまりに＋Aい juga dapat menyatakan terlalu, tetapi rumus utama di sini menghubungkan sebab dan akibat.', 'あまり～ない berarti tidak begitu; あまり tanpa negasi dalam pola ini berarti berlebihan sampai menimbulkan akibat.', '緊張のあまり、名前を忘れてしまいました。|きんちょうの あまり、なまえを わすれてしまいました。|Karena terlalu gugup, saya sampai lupa nama.', '心配するあまり、何度も電話しました。|しんぱいする あまり、なんども でんわしました。|Karena terlalu khawatir, saya menelepon berkali-kali.', '緊張（　）あまり、名前を忘れてしまいました。', 'の|な|に|を', '緊張 adalah kata benda dan mengikuti rumus Nのあまり.'))

lesson('Penilaian dan penyangkalan', 'Tidak berarti demikian dan mustahil demikian',
point('～わけではない', 'bukan berarti …; tidak selalu …', 'V普通形／Aい + わけではない; Aな + な／である + わけではない; N + な／である + わけではない', 'Menolak kesimpulan atau generalisasi, bukan selalu menyangkal seluruh kenyataan. Dipakai untuk memperjelas bahwa suatu hal tidak otomatis mengandung arti tertentu.', '好きなわけではない bukan sama dengan pasti benci; yang disangkal adalah kesimpulan bahwa menyukai.', '高い物がいつもいいわけではありません。|たかい ものが いつも いい わけでは ありません。|Barang mahal tidak selalu bagus.', '日本に住んでいるからといって、漢字が全部読めるわけではありません。|にほんに すんでいるからといって、かんじが ぜんぶ よめる わけでは ありません。|Tinggal di Jepang bukan berarti bisa membaca semua kanji.', 'Tolak generalisasi barang mahal selalu baik: 高い物がいつもいい（　）。', 'わけではありません|わけにはいきません|ためにします|最中にします', 'わけではない menyangkal kesimpulan umum. わけにはいかない menyatakan kendala melakukan tindakan.'),
point('～わけがない', 'tidak mungkin …', 'V普通形／Aい + わけがない; Aな + な + わけがない; N + の／である + わけがない', 'Pembicara menolak kemungkinan dengan keyakinan kuat berdasarkan alasan atau penilaian. Lebih kuat daripada sekadar tidak begitu yakin.', 'Bedakan わけがない yang menolak kemungkinan dari わけではない yang membatasi suatu kesimpulan.', '一日で全部覚えられるわけがありません。|いちにちで ぜんぶ おぼえられる わけが ありません。|Tidak mungkin bisa menghafal semuanya dalam satu hari.', '彼がそんなうそをつくわけがありません。|かれが そんな うそを つく わけが ありません。|Tidak mungkin dia berbohong seperti itu.', 'Keyakinan bahwa mustahil menghafal semuanya sehari: 一日で全部覚えられる（　）。', 'わけがありません|ことにしました|ようにします|ところでした', 'わけがない menolak kemungkinan dengan kuat.'))

lesson('Dugaan dan kepastian', 'Ekspektasi yang gagal dan kepastian negatif',
point('～はずだった', 'seharusnya … menurut rencana atau perkiraan sebelumnya', 'V普通形／Aい + はずだった; Aな + なはずだった; N + のはずだった', 'Menyatakan ekspektasi di masa lalu. Sering dikontraskan dengan kenyataan yang berbeda, tetapi はずだった sendiri tidak selalu membuktikan rencana gagal tanpa konteks.', 'Bukan nasihat moral seperti べきだった. はず berangkat dari jadwal, informasi, atau alasan yang dimiliki pembicara.', '今日は晴れるはずでしたが、雨が降りました。|きょうは はれる はずでしたが、あめが ふりました。|Menurut perkiraan hari ini seharusnya cerah, tetapi hujan turun.', '会議は三時に終わるはずでしたが、長引きました。|かいぎは さんじに おわる はずでしたが、ながびきました。|Rapat seharusnya selesai pukul tiga, tetapi berlangsung lebih lama.', 'Ekspektasi sebelumnya lalu berbeda kenyataan: 今日は晴れる（　）が、雨が降りました。', 'はずでした|べきです|わけにはいきません|最中でした', 'はずでした menyatakan perkiraan sebelumnya; klausa が menunjukkan kenyataan yang berbeda.'),
point('～はずがない', 'tidak mungkin … menurut alasan yang ada', 'V普通形／Aい + はずがない; Aな + なはずがない; N + のはずがない', 'Menolak kemungkinan karena bertentangan dengan informasi atau penalaran pembicara. Maknanya dapat dekat dengan わけがない; bukan perbedaan mutlak antara logika dan emosi.', 'はずがない berarti mustahil menurut perkiraan, bukan kewajiban untuk tidak melakukan.', '鍵をかけたので、ドアが開いているはずがありません。|かぎを かけたので、ドアが あいている はずが ありません。|Karena sudah dikunci, tidak mungkin pintunya terbuka.', '彼は海外にいるので、ここにいるはずがありません。|かれは かいがいに いるので、ここに いる はずが ありません。|Karena dia di luar negeri, tidak mungkin dia berada di sini.', 'Tidak mungkin dia di sini karena sedang di luar negeri: ここにいる（　）。', 'はずがありません|べきではありません|ことはありません|ついでです', 'はずがない menyangkal kemungkinan berdasarkan informasi keberadaannya di luar negeri.'))

lesson('Dugaan dan kepastian', 'Keyakinan kuat dan kesimpulan yang tidak mutlak',
point('～に違いない', 'pasti … menurut keyakinan pembicara', 'V普通形／Aい + に違いない; Aな／N（tanpa だ） + に違いない', 'Dugaan dengan keyakinan kuat berdasarkan petunjuk. Tetap merupakan penilaian pembicara, bukan jaminan fakta telah diverifikasi.', 'Kata benda dan sifat な tidak memakai だ tepat sebelum に違いない: 学生に違いない.', '電気がついているので、誰かいるに違いありません。|でんきが ついているので、だれか いるに ちがいありません。|Karena lampunya menyala, pasti ada seseorang di sana.', '彼は毎日練習しているので、上手に違いありません。|かれは まいにち れんしゅうしているので、じょうずに ちがいありません。|Karena dia berlatih setiap hari, pasti dia mahir.', 'Sifat な langsung diikuti pola dugaan kuat: 彼は上手（　）。', 'に違いありません|だに違いありません|なに違いありません|を違いません', '上手 adalah sifat な tetapi sebelum に違いない tidak memakai だ atau な.'),
point('～とは限らない', 'belum tentu …; tidak selalu …', 'V普通形／Aい + とは限らない; Aな／N + だとは限らない', 'Menegaskan bahwa pernyataan bukan kebenaran universal dan ada kemungkinan pengecualian. Sering muncul bersama 必ずしも atau いつも.', 'Bukan penyangkalan total. 安いとは限らない tidak berarti semuanya mahal.', '有名な店がおいしいとは限りません。|ゆうめいな みせが おいしいとは かぎりません。|Restoran terkenal belum tentu enak.', '努力すれば必ず成功するとは限りません。|どりょくすれば かならず せいこうするとは かぎりません。|Berusaha tidak selalu menjamin keberhasilan.', 'Belum tentu restoran terkenal enak: 有名な店がおいしい（　）。', 'とは限りません|に決まりました|ように言います|ことにします', 'とは限らない membatasi generalisasi; bukan berarti semua restoran terkenal tidak enak.'))

lesson('Dugaan dan informasi', 'Informasi belum pasti dan penampilan khas',
point('～らしい：推量・伝聞', 'tampaknya atau kabarnya …', 'V普通形／Aい + らしい; Aな／N（tanpa だ） + らしい', 'Kesimpulan dari kabar atau petunjuk tidak langsung. Dapat melaporkan informasi yang belum dikonfirmasi. Dibanding そうだ sebagai laporan, らしい juga mudah membawa kesan dugaan pembicara.', 'Dalam dugaan, jangan menambahkan だ setelah kata benda: 学生らしい. Bedakan dari Nらしい yang berarti khas.', '天気予報によると、明日は雪らしいです。|てんきよほうに よると、あしたは ゆきらしいです。|Menurut prakiraan cuaca, kabarnya besok turun salju.', '隣の店は閉店するらしいです。|となりの みせは へいてんするらしいです。|Kabarnya toko sebelah akan tutup permanen.', 'Kabarnya besok bersalju: 明日は雪（　）です。', 'らしい|だらしい|ならしい|のらしい', 'Kata benda 雪 langsung diikuti らしい dalam dugaan.'),
point('Nらしい', 'khas …; sesuai sifat atau peran …', 'N + らしい; bentuk penghubung: らしく／らしいN', 'Menilai bahwa sifat atau perilaku sesuai citra khas suatu kategori. Dalam 子供らしい, yang dibicarakan ialah karakter khas anak, bukan kabar bahwa orang itu seorang anak.', 'Makna dugaan dan kekhasan dapat sama-sama berbentuk Nらしい. Tentukan melalui konteks, jangan hanya melihat rumus.', '今日は春らしい暖かい日です。|きょうは はるらしい あたたかい ひです。|Hari ini hangat, khas musim semi.', '最後まで頑張るのは、彼らしいです。|さいごまで がんばるのは、かれらしいです。|Berusaha sampai akhir itu khas dirinya.', 'Hari hangat khas musim semi: 春（　）暖かい日です。', 'らしい|だらしい|のらしい|ならしい', '春らしい menerangkan sifat khas musim, bukan kabar bahwa hari ini musim semi.'))

lesson('Pertentangan dan penilaian', 'Tidak sesuai harapan dan kritik tajam',
point('～わりに（は）', 'meskipun …, hasilnya relatif …', 'V普通形／Aい + わりに; Aな + なわりに; N + のわりに', 'Hasil berbeda dari perkiraan yang dibuat berdasarkan tingkat, kondisi, harga, atau usaha. Penilaian dapat positif maupun negatif.', 'Kata benda memakai の. Jangan menyamakan わりに dengan perbandingan dua benda secara umum seperti に比べて.', 'この部屋は家賃のわりに広いです。|この へやは やちんの わりに ひろいです。|Kamar ini luas dibandingkan harga sewanya.', 'たくさん勉強したわりに、点数が低かったです。|たくさん べんきょうした わりに、てんすうが ひくかったです。|Nilainya rendah meskipun sudah belajar banyak.', 'この部屋は家賃（　）わりに広いです。', 'の|な|を|と', '家賃 adalah kata benda: 家賃のわりに. Luas kamar melebihi harapan berdasarkan sewanya.'),
point('～くせに', 'padahal …, tetapi …; dasar …', 'V普通形／Aい + くせに; Aな + なくせに; N + のくせに', 'Menyampaikan ketidaksesuaian dengan kritik, kesal, atau ejekan. Lebih tajam daripada のに. Hindari dalam percakapan sopan dengan atasan atau orang yang belum akrab.', 'くせに bukan penghubung netral. Pemakaian kepada orang lain dapat terdengar merendahkan.', '彼は知っているくせに、教えてくれません。|かれは しっている くせに、おしえてくれません。|Padahal dia tahu, tetapi tidak mau memberi tahu saya.', '弟は約束したくせに、来ませんでした。|おとうとは やくそくした くせに、きませんでした。|Padahal adik sudah berjanji, tetapi dia tidak datang.', 'Dengan nada kesal karena ia tahu tetapi merahasiakan: 知っている（　）、教えてくれません。', 'くせに|おかげで|ために|ついでに', 'くせに menghubungkan keadaan dengan hasil yang dikritik.'))

lesson('Pertentangan dan penilaian', 'Standar suatu kategori dan dua sisi',
point('～にしては', 'untuk ukuran …, ternyata …', 'V普通形 + にしては; N + にしては', 'Menggunakan suatu kategori atau fakta sebagai standar, lalu hasilnya tidak sesuai harapan. Contoh: pemula tetapi mahir. Berbeda dari わりに yang mudah dipakai dengan ukuran bertingkat seperti harga atau usaha.', 'Kata benda langsung diikuti にしては, tanpa の. Hindari menganggap わりに dan にしては selalu dapat saling menggantikan.', '彼は初心者にしては上手です。|かれは しょしんしゃにしては じょうずです。|Untuk ukuran pemula, dia mahir.', '昨日買ったにしては、もう汚れています。|きのう かったにしては、もう よごれています。|Padahal baru dibeli kemarin, barangnya sudah kotor.', '彼は初心者（　）上手です。', 'にしては|のにしては|なにしては|をしては', '初心者 merupakan standar kategori; langsung memakai にしては.'),
point('～反面', 'di sisi lain …', 'V普通形／Aい + 反面; Aな + な反面; N + である反面', 'Membandingkan dua sisi berbeda dari hal yang sama, sering keuntungan dengan kerugian. Kedua sisi dapat sama-sama benar.', 'Tidak sekadar menyatakan urutan dua peristiwa. Sisi kedua harus menjadi aspek yang berlawanan atau berbeda secara bermakna.', 'この仕事は忙しい反面、やりがいがあります。|この しごとは いそがしい はんめん、やりがいが あります。|Pekerjaan ini sibuk, tetapi di sisi lain memberi kepuasan.', '一人暮らしは自由な反面、寂しいこともあります。|ひとりぐらしは じゆうな はんめん、さびしいことも あります。|Tinggal sendiri memberi kebebasan, tetapi kadang juga terasa sepi.', 'Sifat な dihubungkan dengan dua sisi: 一人暮らしは自由（　）反面、寂しいこともあります。', 'な|の|を|と', '自由 merupakan sifat な, sehingga 自由な反面.'))

lesson('Pertentangan dan penilaian', 'Meluruskan sebutan dan menolak kesimpulan',
point('～というより', 'lebih tepat disebut … daripada …', 'V普通形／Aい + というより; Aな／N（だ boleh muncul） + というより', 'Menyebut label pertama lalu menggantinya dengan penilaian yang lebih tepat. Sering dipasangkan dengan むしろ, tetapi むしろ tidak wajib.', 'Berbeda dari より untuk perbandingan jumlah, pola ini meluruskan deskripsi atau penilaian.', '彼は怒っているというより、困っているようです。|かれは おこっているというより、こまっているようです。|Dia tampaknya lebih kebingungan daripada marah.', 'ここは店というより、家のようです。|ここは みせというより、いえのようです。|Tempat ini lebih seperti rumah daripada toko.', 'Meluruskan bahwa ia lebih bingung daripada marah: 怒っている（　）、困っているようです。', 'というより|たびに|ためだけに|最中に', 'というより mengganti penilaian pertama dengan penilaian yang dirasa lebih tepat.'),
point('～からといって', 'hanya karena …, bukan berarti …', 'V普通形／Aい + からといって; Aな／N + だからといって', 'Menolak kesimpulan otomatis dari satu alasan. Biasanya diikuti penyangkalan generalisasi seperti わけではない atau とは限らない.', 'Pola ini bukan sekadar sebab positif seperti から. Klausa kedua lazim menolak kesimpulan yang terlalu luas.', '安いからといって、悪い物とは限りません。|やすいからといって、わるい ものとは かぎりません。|Hanya karena murah, belum tentu barangnya buruk.', '大人だからといって、何でも知っているわけではありません。|おとなだからといって、なんでも しっている わけでは ありません。|Menjadi orang dewasa bukan berarti mengetahui segalanya.', 'Kata benda 大人 sebelum penolakan generalisasi: 大人（　）、何でも知っているわけではありません。', 'だからといって|なからといって|のからといって|をからといって', 'Kata benda dalam sebab memakai だ: 大人だからといって.'))

lesson('Penambahan dan penekanan', 'Bukan hanya dan kejutan bahkan',
point('～ばかりでなく', 'bukan hanya …, tetapi juga …', 'V普通形／Aい + ばかりでなく; Aな + な／である + ばかりでなく; N + ばかりでなく', 'Menambahkan informasi yang searah. Klausa kedua sering memakai も. Makna dasarnya dekat dengan だけでなく, tetapi sering digunakan dalam penjelasan atau tulisan.', 'Bukan ばかり yang berarti hanya atau terus saja. Ada bagian kedua yang menambah cakupan.', 'この店は安いばかりでなく、おいしいです。|この みせは やすい ばかりでなく、おいしいです。|Restoran ini bukan hanya murah, tetapi juga enak.', '彼は英語ばかりでなく、中国語も話せます。|かれは えいごばかりでなく、ちゅうごくごも はなせます。|Dia bukan hanya bisa berbahasa Inggris, tetapi juga Mandarin.', 'Bukan hanya murah tetapi enak: 安い（　）、おいしいです。', 'ばかりでなく|せいで|とたんに|わけがなく', 'ばかりでなく menambahkan kelebihan lain, bukan akibat atau urutan waktu.'),
point('～さえ', 'bahkan …', 'N（+ partikel yang sesuai） + さえ; Vます語幹 + さえする', 'Menunjukkan contoh yang mengejutkan atau pada batas ekstrem. は／が／を biasanya digantikan; に atau で dapat dipertahankan seperti にさえ.', 'さえ sering berdekatan makna dengan も, tetapi memberi penekanan “bahkan” yang lebih kuat. Cek partikel asal sebelum mengganti.', '忙しくて、昼ご飯さえ食べられませんでした。|いそがしくて、ひるごはんさえ たべられませんでした。|Saya sangat sibuk sampai makan siang pun tidak sempat.', 'この問題は先生にさえ難しいです。|この もんだいは せんせいにさえ むずかしいです。|Soal ini sulit bahkan bagi guru.', 'Sangat sibuk, bahkan makan siang tak sempat: 昼ご飯（　）食べられませんでした。', 'さえ|こそ|によって|に関して', 'さえ menekankan bahwa kebutuhan dasar seperti makan siang pun tidak bisa dilakukan.'))

lesson('Penambahan dan penekanan', 'Justru yang ditekankan dan cukup satu syarat',
point('～こそ', 'justru …; …lah yang penting', 'N + こそ; sebab から + こそ', 'Menekankan unsur sebagai yang benar-benar penting atau tepat, sering mengontraskan dengan kesempatan atau hal lain. からこそ menegaskan alasan.', 'こそ bukan “bahkan”; untuk contoh yang mengejutkan gunakan さえ. Jangan menumpuk はこそ dalam pola dasar topik.', '今年こそ合格したいです。|ことしこそ ごうかくしたいです。|Tahun inilah saya benar-benar ingin lulus.', '大切な友達だからこそ、本当のことを言います。|たいせつな ともだちだからこそ、ほんとうの ことを いいます。|Justru karena kamu teman berharga, saya mengatakan yang sebenarnya.', 'Penekanan “tahun inilah”: 今年（　）合格したいです。', 'こそ|さえも|について|によると', 'こそ menegaskan tahun ini sebagai kesempatan yang ingin diwujudkan.'),
point('～さえ～ば', 'asalkan … saja, maka …', 'N + さえ + Vば; Vます語幹 + さえすれば; Aい→くさえあれば; Aな／N + でさえあれば', 'Menjadikan satu syarat sebagai syarat minimal yang cukup. Unsur yang menjadi fokus diletakkan sebelum さえ; hasil biasanya suatu kemungkinan atau keinginan.', 'Berbeda dari さえ biasa yang berarti bahkan. Bentuk bersyarat ば pada bagian berikut diperlukan untuk makna “asalkan”.', '時間さえあれば、参加できます。|じかんさえ あれば、さんかできます。|Asalkan ada waktu, saya bisa ikut.', '練習しさえすれば、上手になります。|れんしゅうしさえ すれば、じょうずに なります。|Asalkan berlatih, Anda akan menjadi lebih mahir.', '時間さえ（　）、参加できます。', 'あれば|あるときに|あった最中|ありますが', 'さえ＋あれば membentuk syarat minimal: asalkan ada waktu.'))

lesson('Topik dan arah sikap', 'Mengenai topik dan terhadap sasaran',
point('～について', 'tentang …', 'N + について; N + についての + N', 'Menetapkan topik untuk berbicara, menulis, meneliti, atau berpikir. Untuk menerangkan kata benda setelahnya, tambahkan の.', 'Nについての本 benar; Nについて本 tanpa の bukan bentuk penerang kata benda yang diajarkan.', '日本の文化について調べています。|にほんの ぶんかについて しらべています。|Saya sedang meneliti budaya Jepang.', 'これは環境についての本です。|これは かんきょうについての ほんです。|Ini buku tentang lingkungan.', 'Buku tentang lingkungan: 環境について（　）本です。', 'の|な|を|で', 'Pola yang menerangkan 本 ialah についての＋N.'),
point('～に対して', 'terhadap …; kepada …', 'N + に対して; N + に対する + N', 'Menunjukkan sasaran sikap, respons, atau tindakan. Bentuk penerang kata benda ialah に対する. Dalam konteks lain dapat mengontraskan dua klausa; lesson ini berfokus pada sasaran.', 'について menandai topik, sedangkan に対して menunjukkan arah sikap atau tindakan. Tidak selalu dapat saling menggantikan.', 'お客様に対して、丁寧に話してください。|おきゃくさまにたいして、ていねいに はなしてください。|Tolong berbicara sopan kepada pelanggan.', '彼は仕事に対する責任感が強いです。|かれは しごとにたいする せきにんかんが つよいです。|Dia mempunyai rasa tanggung jawab yang kuat terhadap pekerjaan.', 'Penerang kata benda 責任感: 仕事（　）責任感が強いです。', 'に対する|に対してのを|に対したら|に対しています', 'に対する menerangkan kata benda 責任感 sebagai sasaran rasa tanggung jawab.'))

lesson('Sudut pandang dan peran', 'Bagi seseorang dan sebagai suatu peran',
point('～にとって', 'bagi … dari sudut pandangnya', 'N + にとって; N + にとっての + N', 'Menilai penting, sulit, bermanfaat, atau bernilai dari sudut pandang orang atau kelompok. Biasanya diikuti penilaian, bukan sasaran tindakan.', '私にとって難しい adalah penilaian; 私に対して話す adalah tindakan kepada saya. Jangan mengganti keduanya begitu saja.', '私にとって、家族が一番大切です。|わたしにとって、かぞくが いちばん たいせつです。|Bagi saya, keluarga adalah yang paling penting.', 'この仕事は彼にとって難しいです。|この しごとは かれにとって むずかしいです。|Pekerjaan ini sulit bagi dia.', 'Penilaian dari sudut pandang saya: 私（　）、家族が一番大切です。', 'にとって|に対する|によるとを|をとって', 'にとって menandai sudut pandang yang digunakan dalam penilaian.'),
point('～として', 'sebagai …', 'N + として; N + としての + N', 'Menyatakan status, peran, atau fungsi saat melakukan tindakan. Berbeda dari にとって yang berfokus pada penilaian dari sudut pandang.', 'Gunakan としての untuk menerangkan kata benda: 教師としての経験.', '彼は医者として働いています。|かれは いしゃとして はたらいています。|Dia bekerja sebagai dokter.', 'これは友達としてのアドバイスです。|これは ともだちとしての アドバイスです。|Ini nasihat saya sebagai teman.', 'Penerang kata benda アドバイス: 友達として（　）アドバイスです。', 'の|な|を|で', 'としての＋N menyatakan peran yang melandasi nasihat.'))

lesson('Sarana dan sumber informasi', 'Menurut keadaan dan menurut sumber',
point('～によって', 'bergantung pada …; melalui …; oleh …', 'N + によって; N + による + N', 'Makna ditentukan konteks: variasi menurut orang atau keadaan, sarana untuk menghasilkan sesuatu, sebab, atau pelaku dalam pasif formal. Contoh di sini berfokus pada variasi dan pelaku karya.', 'によって tidak selalu berarti “menurut sumber berita”. Untuk melaporkan sumber gunakan によると atau によれば.', '人によって、考え方が違います。|ひとによって、かんがえかたが ちがいます。|Cara berpikir berbeda menurut orangnya.', 'この小説は有名な作家によって書かれました。|この しょうせつは ゆうめいな さっかによって かかれました。|Novel ini ditulis oleh seorang penulis terkenal.', 'Variasi antarorang: 人（　）、考え方が違います。', 'によって|についての|としての|にとっての', '人によって menandai faktor yang membuat hasil bervariasi, bukan topik atau sudut pandang penilaian.'),
point('～によると／～によれば', 'menurut sumber …', 'N sumber informasi + によると／によれば', 'Menandai asal informasi yang dilaporkan. Klausa berikut sering memakai そうだ, らしい, atau ということだ untuk menunjukkan informasi bukan pengamatan langsung pembicara.', 'Untuk variasi orang gunakan 人によって, bukan 人によると kecuali orang tersebut benar-benar sumber ucapan.', 'ニュースによると、来月新しい駅ができるそうです。|ニュースによると、らいげつ あたらしい えきが できるそうです。|Menurut berita, kabarnya stasiun baru akan selesai bulan depan.', '先生によれば、試験は来週だそうです。|せんせいによれば、しけんは らいしゅうだそうです。|Menurut guru, kabarnya ujian diadakan minggu depan.', 'Sumber kabar berupa berita: ニュース（　）、来月新しい駅ができるそうです。', 'によると|にとって|として|に対する', 'によると menandai sumber berita; そうです mengakhiri laporan informasi.'))

lesson('Perbandingan dan derajat', 'Membandingkan dan tidak mencapai tingkat',
point('～に比べて', 'dibandingkan dengan …', 'N + に比べて; V普通形 + のに比べて', 'Menjadikan sesuatu sebagai standar lalu menjelaskan perbedaan. Dapat membandingkan harga, tingkat, keadaan, atau perubahan antartahun.', '比べて dibaca くらべて. Untuk tindakan yang menjadi standar, nominalkan dengan の.', '去年に比べて、今年は暑いです。|きょねんに くらべて、ことしは あついです。|Dibanding tahun lalu, tahun ini panas.', '電車に比べて、バスは安いです。|でんしゃに くらべて、バスは やすいです。|Dibanding kereta, bus lebih murah.', '去年（　）、今年は暑いです。', 'に比べて|に比べるの|を比べての|の比べて', 'Nに比べて menjadikan tahun lalu sebagai standar perbandingan.'),
point('～ほど～ない', 'tidak se…', 'N + ほど + predikat negatif; V普通形 + ほど + predikat negatif', 'Menyatakan hal pertama tidak mencapai tingkat standar pembanding. Fokus latihan N3 di sini ialah memahami arah perbandingan, termasuk perkiraan yang ternyata berlebihan.', 'AはBほど高くない berarti A lebih rendah tingkat mahalnya daripada B, bukan sebaliknya.', '今日は昨日ほど寒くありません。|きょうは きのうほど さむくありません。|Hari ini tidak sedingin kemarin.', 'この仕事は思っていたほど難しくありません。|この しごとは おもっていたほど むずかしくありません。|Pekerjaan ini tidak sesulit yang saya bayangkan.', 'Hari ini tidak sedingin kemarin: 今日は昨日（　）寒くありません。', 'ほど|だけに|さえも|こそ', 'ほど dengan predikat negatif membandingkan tingkat: dingin hari ini tidak mencapai tingkat kemarin.'))

lesson('Perbandingan dan derajat', 'Perubahan seiring tingkat dan gambaran intensitas',
point('～ば～ほど', 'semakin …, semakin …', 'Vば + V辞書形 + ほど; Aい→ければ + Aい + ほど; Aな + なら／であれば + Aな + なほど', 'Dua tingkat berubah bersama. Kata yang menjadi ukuran biasanya diulang: 読めば読むほど, 安ければ安いほど. Hubungan dapat positif maupun negatif.', 'Jangan memakai bentuk たら pada bagian pertama dalam pola pengulangan ini. 安ければ安いほど memakai sifat い tanpa です.', '練習すればするほど、上手になります。|れんしゅうすれば するほど、じょうずに なります。|Semakin berlatih, semakin mahir.', '荷物は少なければ少ないほど、楽です。|にもつは すくなければ すくないほど、らくです。|Semakin sedikit barang bawaan, semakin ringan perjalanan.', '練習（　）するほど、上手になります。', 'すれば|したら|して|した', 'Pengulangan bersyarat yang menyatakan semakin ialah すればするほど.'),
point('～くらい／～ほど：程度', 'sampai tingkat …', 'V普通形／Aい + くらい／ほど; Aな + なくらい／なほど; N + くらい／ほど', 'Memberi gambaran tingkat melalui contoh atau perbandingan. Pada contoh 感動して泣くほど, menangis menjadi ukuran kuatnya perasaan, bukan syarat wajib.', 'Jangan selalu menafsirkan くらい sebagai perkiraan jumlah. Di sini klausa menjadi gambaran intensitas.', '声が出ないくらい驚きました。|こえが でないくらい おどろきました。|Saya sangat terkejut sampai tidak bisa bersuara.', '涙が出るほど感動しました。|なみだが でるほど かんどうしました。|Saya begitu tersentuh sampai meneteskan air mata.', 'Intensitas sangat tersentuh: 涙が出る（　）感動しました。', 'ほど|たびに|前だけ|によると', 'ほど memakai keluarnya air mata sebagai gambaran tingkat keterharuan.'))

lesson('Pengandaian', 'Walaupun hipotesis dan prasyarat yang wajib',
point('～たとえ～ても', 'sekalipun …, tetap …', 'たとえ + Vて／Aい→くて／Aな・N→で + も', 'Mengandaikan kondisi yang kuat atau ekstrem, tetapi keputusan atau hasil tetap tidak berubah. たとえ memberi penekanan hipotetis; ても sendiri juga dipakai untuk fakta.', 'たとえ dipasangkan dengan ても／でも, bukan otomatis dengan たら. Setelah sifat い gunakan くても.', 'たとえ雨が降っても、参加します。|たとえ あめが ふっても、さんかします。|Sekalipun hujan turun, saya tetap akan ikut.', 'たとえ高くても、このかばんを買いたいです。|たとえ たかくても、この かばんを かいたいです。|Sekalipun mahal, saya tetap ingin membeli tas ini.', 'たとえ（　）、このかばんを買いたいです。', '高くても|高いでも|高かったら|高くては', 'Sifat い diubah menjadi 高くても untuk pengandaian konsesif.'),
point('～ないことには', 'kalau tidak …, tidak akan bisa …', 'Vない形 + ことには + predikat negatif', 'Menekankan bahwa tindakan atau keadaan pertama merupakan syarat minimum bagi hasil kedua. Tanpa tindakan pertama, hasil tidak dapat dicapai atau dinilai.', 'Bagian akhir lazim negatif. Pola ini bukan pengandaian hasil positif yang bebas.', '実際に使ってみないことには、便利かどうか分かりません。|じっさいに つかってみないことには、べんりかどうか わかりません。|Kalau tidak mencoba memakainya langsung, saya tidak tahu apakah praktis.', '話し合わないことには、問題は解決しません。|はなしあわないことには、もんだいは かいけつしません。|Tanpa berdiskusi, masalah tidak akan selesai.', 'Prasyarat diskusi sebelum masalah selesai: （　）ことには、問題は解決しません。', '話し合わない|話し合う|話し合った|話し合って', 'Vない＋ことには diikuti hasil negatif: tidak berdiskusi berarti masalah tidak selesai.'))

lesson('Penggantian dan pertukaran', 'Sebagai pengganti dan mewakili orang',
point('～代わりに', 'sebagai ganti …; sebagai imbalan …', 'V普通形／Aい + 代わりに; Aな + な代わりに; N + の代わりに', 'Bisa mengganti tindakan atau benda, atau menyatakan pertukaran keuntungan dengan kekurangan. Contoh pertama mengganti kegiatan, kedua menyebut biaya sebagai sisi pengganti kenyamanan.', 'Kata benda memakai の代わりに. Jangan menyamakan semua penggunaan dengan に代わって yang menekankan pengganti pelaku atau peran.', '外で食べる代わりに、家で料理しました。|そとで たべる かわりに、いえで りょうりしました。|Sebagai ganti makan di luar, saya memasak di rumah.', 'この部屋は狭い代わりに、家賃が安いです。|この へやは せまい かわりに、やちんが やすいです。|Kamar ini sempit, tetapi sebagai gantinya sewanya murah.', 'Kegiatan memasak menggantikan makan di luar: 外で食べる（　）、家で料理しました。', '代わりに|たびに|おかげで|最中に', '代わりに menghubungkan tindakan yang diganti dengan tindakan penggantinya.'),
point('～に代わって', 'menggantikan atau mewakili …', 'N orang／kelompok／peran + に代わって', 'Seseorang atau sesuatu menjalankan fungsi yang biasanya dilakukan pihak lain. Bentuk に代わり juga dipakai dalam bahasa formal.', 'Nに代わって menunjuk pihak yang digantikan, bukan pihak penggantinya. Kata benda tidak memakai の dalam rumus ini.', '部長に代わって、私が説明します。|ぶちょうに かわって、わたしが せつめいします。|Saya akan menjelaskan menggantikan kepala bagian.', '母に代わって、私が弟を迎えに行きました。|ははに かわって、わたしが おとうとを むかえに いきました。|Saya menjemput adik laki-laki menggantikan ibu.', '部長（　）、私が説明します。', 'に代わって|の代わって|を代わって|な代わって', '部長に代わって menempatkan kepala bagian sebagai pihak yang digantikan oleh saya.'))

lesson('Kecenderungan dan keadaan', 'Sering terjadi dan gejala ringan',
point('～がち', 'cenderung atau sering …', 'Vます語幹／N + がち; penghubung: がちなN／がちのN', 'Menggambarkan kecenderungan berulang, sering bernilai negatif atau perlu perhatian: 忘れがち, 遅れがち, 病気がち. Bukan pasti terjadi setiap saat.', 'Tidak semua kata sifat dapat langsung ditempeli がち. Kata kerja memakai pangkal ます, bukan bentuk kamus.', '忙しいと、約束を忘れがちです。|いそがしいと、やくそくを わすれがちです。|Saat sibuk, saya cenderung lupa janji.', '最近、授業を休みがちです。|さいきん、じゅぎょうを やすみがちです。|Akhir-akhir ini saya sering tidak masuk kelas.', '忙しいと、約束を（　）がちです。', '忘れ|忘れる|忘れた|忘れて', '忘れます diambil pangkal 忘れ lalu ditambah がち.'),
point('～気味', 'agak …; menunjukkan sedikit gejala …', 'Vます語幹／N + 気味', 'Menunjukkan keadaan ringan atau tanda awal, sering pada kondisi tubuh atau kecenderungan buruk: 疲れ気味, 風邪気味. 気味 dibaca ぎみ pada pola ini.', '気味 menyatakan keadaan agak demikian, bukan frekuensi berulang seperti がち.', '今日は疲れ気味です。|きょうは つかれぎみです。|Hari ini saya agak lelah.', '風邪気味なので、早く寝ます。|かぜぎみなので、はやく ねます。|Karena agak merasa seperti masuk angin, saya akan tidur lebih awal.', 'Agak lelah sekarang: 今日は（　）気味です。', '疲れ|疲れる|疲れた|疲れて', 'Pangkal 疲れ ditambah 気味 menunjukkan keadaan ringan saat ini.'))

lesson('Kecenderungan dan keadaan', 'Terkesan seperti dan penuh sesuatu',
point('～っぽい', 'terkesan seperti …; cenderung …', 'N／sebagian Vます語幹 + っぽい; berkonjugasi seperti Aい', 'Membentuk sifat yang menunjukkan kesan, ciri dominan, atau kecenderungan: 子供っぽい, 忘れっぽい. Kata yang dapat digabung bersifat leksikal; tidak setiap kata bisa diberi っぽい.', 'っぽい biasanya lebih kasual dan dapat bernilai negatif. 子供らしい lebih menekankan karakter khas yang wajar.', '彼の話し方は子供っぽいです。|かれの はなしかたは こどもっぽいです。|Cara bicaranya terkesan kekanak-kanakan.', '最近、忘れっぽくなりました。|さいきん、わすれっぽく なりました。|Akhir-akhir ini saya menjadi mudah lupa.', 'Bentuk penghubung sebelum なる: 忘れっぽ（　）なりました。', 'く|に|な|で', 'っぽい berkonjugasi seperti sifat い, sehingga 忘れっぽくなる.'),
point('～だらけ', 'penuh …', 'N + だらけ; N + だらけの + N', 'Menunjukkan banyak unsur yang tidak diinginkan tersebar atau menempel, seperti kesalahan, lumpur, atau debu. Bukan penanda netral semua jenis isi.', 'Untuk ruangan penuh orang, 人でいっぱい umumnya lebih netral daripada 人だらけ. Pemakaian だらけ memberi penilaian.', 'この作文は間違いだらけです。|この さくぶんは まちがいだらけです。|Karangan ini penuh kesalahan.', '子供は泥だらけの靴で帰ってきました。|こどもは どろだらけの くつで かえってきました。|Anak itu pulang dengan sepatu penuh lumpur.', 'Sepatu penuh lumpur: 泥だらけ（　）靴です。', 'の|な|に|を', 'だらけの＋N menerangkan benda yang penuh unsur tersebut.'))

lesson('Hasil dan beban tindakan', 'Cukup dengan dan bebas dari keharusan',
point('～て済む', 'cukup dengan …; selesai dengan …', 'Vて + 済む', 'Tindakan sudah cukup untuk menyelesaikan masalah atau memenuhi kebutuhan, tanpa membutuhkan tindakan yang lebih berat. 済む dibaca すむ. Variasi Nで済む dan だけで済む juga menyebut sarana atau batas kebutuhan.', 'Pola ini bukan selesai melakukan seperti Vます語幹＋終わる; fokusnya kebutuhan atau masalah yang teratasi.', 'メールを送って済みました。|メールを おくって すみました。|Urusannya selesai dengan mengirim email.', 'その場で説明して済みました。|その ばで せつめいして すみました。|Urusannya selesai dengan menjelaskan di tempat itu.', 'その場で（　）済みました。', '説明して|説明する|説明した|説明しない', 'て済む mengikuti tindakan yang cukup untuk menyelesaikan kebutuhan.'),
point('～ずに済む／～ないで済む', 'tidak perlu … dan masalah tetap selesai', 'Vない形 tanpa ない + ずに済む; する→せずに済む; Vない + で済む', 'Kebutuhan tetap terpenuhi tanpa melakukan tindakan yang biasanya dianggap perlu. Sering menyatakan lega karena terhindar dari biaya, perjalanan, atau pekerjaan tambahan.', 'する berubah menjadi せず, bukan しず. Bedakan dari ことはない sebagai nasihat; ずに済む menggambarkan terselesaikannya kebutuhan.', '友達が送ってくれたので、歩かずに済みました。|ともだちが おくってくれたので、あるかずに すみました。|Teman mengantar saya, jadi saya tidak perlu berjalan kaki.', 'オンラインで申し込めたので、窓口へ行かないで済みました。|オンラインで もうしこめたので、まどぐちへ いかないで すみました。|Karena bisa mendaftar daring, saya tidak perlu pergi ke loket.', 'Tidak perlu berjalan berkat diantar: 歩か（　）済みました。', 'ずに|ないに|ずで|なくに', '歩かない diubah menjadi 歩かずに, lalu ditambah 済む.'))

lesson('Kemungkinan dan tahap belum selesai', 'Tidak ada cara dan baru sebagian',
point('～ようがない', 'tidak ada cara untuk …', 'Vます語幹 + ようがない', 'Tidak dapat melakukan karena cara, sarana, atau informasi yang diperlukan tidak ada. よう di sini berarti cara, bukan bentuk kehendak.', 'Cara melakukan dibentuk dari pangkal ます: 説明しようがない. Jangan menyamakan dengan V意向形＋としない yang berarti enggan.', '連絡先が分からないので、連絡しようがありません。|れんらくさきが わからないので、れんらくしようが ありません。|Karena tidak tahu kontaknya, tidak ada cara untuk menghubunginya.', '資料がないので、確かめようがありません。|しりょうが ないので、たしかめようが ありません。|Karena tidak ada bahan rujukan, tidak ada cara untuk memastikannya.', 'Tidak ada cara memeriksa tanpa data: 資料がないので、（　）ようがありません。', '確かめ|確かめる|確かめた|確かめて', 'Pangkal ます 確かめ ditambah ようがない menyatakan ketiadaan cara.'),
point('～かける／～かけの', 'baru mulai atau belum selesai …', 'Vます語幹 + かける; Vます語幹 + かけの + N', 'Tindakan dimulai tetapi belum selesai, atau hampir mulai. Contoh yang diajarkan berfokus pada benda yang sudah sebagian dikerjakan: 読みかけの本, 食べかけのパン.', 'かけ menunjukkan ketidakselesaian, bukan hasil selesai seperti たばかり. Kata kerja memakai pangkal ます.', '机に読みかけの本があります。|つくえに よみかけの ほんが あります。|Di meja ada buku yang baru saya baca sebagian.', '食べかけのパンを冷蔵庫に入れました。|たべかけの パンを れいぞうこに いれました。|Saya memasukkan roti yang belum habis dimakan ke kulkas.', 'Buku yang dibaca sebagian: （　）かけの本です。', '読み|読む|読んだ|読んで', '読みます diambil pangkal 読み, lalu 読みかけの本 berarti buku yang belum selesai dibaca.'))

lesson('Menjelaskan informasi', 'Melaporkan isi dan mendefinisikan istilah',
point('～ということだ', 'kabarnya …; berarti …', 'V普通形／Aい + ということだ; Aな／N + だということだ', 'Dapat melaporkan informasi dari sumber atau menyimpulkan arti fakta. Sumber yang disebut dan isi kalimat menentukan makna; jangan selalu menerjemahkannya sebagai kabar.', 'Kalimat nominal dalam kutipan memakai だ: 休みだということだ. Kesimpulan pembicara perlu didukung konteks.', 'ニュースによると、橋は来月完成するということです。|ニュースによると、はしは らいげつ かんせいするということです。|Menurut berita, kabarnya jembatan akan selesai bulan depan.', '返事がないのは、まだ決めていないということです。|へんじが ないのは、まだ きめていないということです。|Tidak adanya jawaban berarti keputusan belum dibuat.', 'Laporan kutipan nominal: 明日は休み（　）ことです。', 'だという|なという|のという|をいう', 'Isi kutipan nominal ialah 休みだ; ditambah ということです menjadi laporan.'),
point('～というのは', 'yang disebut … adalah …', 'N istilah + というのは; klausa + というのは', 'Memperkenalkan istilah atau tindakan sebagai topik yang akan didefinisikan atau dijelaskan. Penjelasan sering diakhiri ことだ untuk tindakan atau ものだ untuk benda.', 'というのは tidak selalu definisi kamus; dapat menempatkan suatu peristiwa atau ucapan sebagai topik penjelasan.', 'リサイクルというのは、使った物をもう一度利用することです。|リサイクルというのは、つかった ものを もういちど りようすることです。|Daur ulang adalah menggunakan kembali barang yang telah dipakai.', '締め切りというのは、提出しなければならない最後の日です。|しめきりというのは、ていしゅつしなければならない さいごの ひです。|Tenggat adalah hari terakhir sesuatu harus diserahkan.', 'Mendefinisikan istilah: リサイクル（　）、使った物をもう一度利用することです。', 'というのは|によっては|に対しては|の最中は', 'というのは memperkenalkan istilah yang dijelaskan maknanya.'))

lesson('Kausatif dan kesopanan', 'Terpaksa melakukan dan izin yang dihargai',
point('使役受身：～させられる', 'disuruh atau dipaksa melakukan …', '五段: ない形 tanpa ない + せられる（bentuk singkat ～される, kecuali ～す）; 一段: る→させられる; する→させられる; 来る→来させられる', 'Gabungan kausatif dan pasif: pelaku melakukan tindakan atas tekanan orang lain. Pelaku tindakan memakai は／が; pihak yang menyuruh memakai に. Contoh 五段: 書かせられる→書かされる; 話す→話させられる.', 'Bedakan pasif biasa 読まれる dari kausatif pasif 読まされる. Bentuk singkat tidak dipakai untuk kata kerja 五段 berakhiran す.', '子供の時、毎日野菜を食べさせられました。|こどもの とき、まいにち やさいを たべさせられました。|Saat kecil, saya disuruh makan sayuran setiap hari.', '先生に作文を書かされました。|せんせいに さくぶんを かかされました。|Saya disuruh guru menulis karangan.', 'Kausatif pasif singkat dari 書く: 先生に作文を（　）。', '書かされました|書かれました|書きました|書けました', '書かせられる dapat disingkat menjadi 書かされる. 書かれる hanya bentuk pasif biasa.'),
point('～させていただく', 'mohon izin untuk …; diizinkan melakukan dengan rasa terima kasih', 'V使役形て + いただく', 'Pembicara melakukan tindakan dengan izin pihak lain dan merasakan manfaat izin tersebut. Cocok misalnya saat meminta izin menjelaskan. Tidak perlu dipakai untuk semua tindakan diri sendiri; untuk pernyataan sederhana, いたします sering cukup.', 'Pelaku tindakan ialah pembicara, bukan pihak yang dihormati. Bedakan 説明していただく: orang lain menjelaskan untuk kita.', '私から説明させていただきます。|わたしから せつめいさせて いただきます。|Dengan izin Anda, saya akan menjelaskan terlebih dahulu.', '今日は早く帰らせていただけませんか。|きょうは はやく かえらせて いただけませんか。|Bolehkah saya mendapat izin pulang lebih awal hari ini?', 'Pembicara meminta izin melakukan penjelasan: 私から（　）いただきます。', '説明させて|説明して|説明されて|説明しなくて', '説明させていただく berarti saya melakukan penjelasan dengan izin. 説明していただく berarti orang lain menjelaskan untuk saya.'))

lesson('Kebiasaan dan kenangan', 'Sifat umum dan kebiasaan masa lalu',
point('～ものだ：一般的な性質', 'memang pada umumnya …', 'V辞書形／Vない形／Aい + ものだ; Aな + なものだ', 'Mengungkapkan sifat umum, kecenderungan yang dianggap wajar, atau rasa takjub pada kenyataan umum. Contoh di sini menjelaskan pengalaman manusia secara umum, bukan benda fisik.', 'Pola ものだ memiliki beberapa fungsi. Vたものだ untuk nostalgia berbeda dari penjelasan sifat umum dengan bentuk nonlampau.', '時間がたつと、記憶は薄くなるものです。|じかんが たつと、きおくは うすくなる ものです。|Seiring waktu, ingatan memang biasanya memudar.', '新しいことを始める時は、不安になるものです。|あたらしい ことを はじめる ときは、ふあんに なる ものです。|Saat mulai hal baru, orang memang biasanya merasa cemas.', 'Penjelasan kecenderungan umum: 記憶は薄くなる（　）です。', 'もの|ところ|たび|ついで', 'ものだ mengungkapkan kecenderungan yang dianggap umum, bukan tahap tindakan.'),
point('～たものだ', 'dulu sering …; mengenang kebiasaan masa lalu', 'Vた + ものだ', 'Pembicara mengenang kebiasaan yang berulang pada masa lalu, sering dengan perasaan nostalgia. Biasanya didukung kata waktu seperti 子供のころ atau 昔.', 'Bukan satu kejadian yang baru selesai. Untuk satu pengalaman gunakan たことがある; たものだ mengingat kebiasaan.', '子供のころ、この川でよく泳いだものです。|こどもの ころ、この かわで よく およいだ ものです。|Dulu saat kecil, saya sering berenang di sungai ini.', '学生のころ、友達と夜遅くまで話したものです。|がくせいの ころ、ともだちと よる おそくまで はなした ものです。|Dulu saat menjadi pelajar, saya sering berbicara dengan teman sampai larut malam.', 'Kenangan kebiasaan dulu: 子供のころ、よく（　）ものです。', '泳いだ|泳ぐ|泳いで|泳がない', 'Kenangan kebiasaan lampau menggunakan Vた＋ものだ: 泳いだものだ.'))

def build():
    pool = [e for l in LESSONS for p in l['points'] for e in p['examples']]
    for l in LESSONS:
        questions = []
        for p in l['points']:
            questions.append(p.pop('practice'))
        for p in l['points']:
            e = p['examples'][0]
            related = [x for q in l['points'] for x in q['examples'] if x['meaning'] != e['meaning']]
            choices = [e['meaning']] + [x['meaning'] for x in related][:3]
            questions.append(dict(prompt='Kalimat ini bermakna apa?\n' + e['japanese'],
                                  choices=choices, correct=0,
                                  explanation=p['pattern'] + ': ' + p['meaning'] + '.\n' + e['reading'] + '\n' + e['meaning']))
        target = l['points'][1]['examples'][1]
        alternatives = [x['japanese'] for p in l['points'] for x in p['examples'] if x['japanese'] != target['japanese']]
        questions.append(dict(prompt='Pilih kalimat yang sesuai situasi atau maksud berikut:\n' + target['meaning'],
                              choices=[target['japanese']] + alternatives[:3], correct=0,
                              explanation=l['points'][1]['pattern'] + ': ' + l['points'][1]['explanation'] + '\n' + target['reading'] + '\n' + target['meaning']))
        l['questions'] = questions
    output = Path('backend/data/grammar/n3.json')
    output.write_text(json.dumps(LESSONS, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
    rows = [f"| {i:02d} | {l['chapter']} | {l['title']} | {'; '.join(p['pattern'] for p in l['points'])} |" for i, l in enumerate(LESSONS, 1)]
    Path('build/grammar-n3-curriculum.md').write_text('\n'.join(rows), encoding='utf-8')
    print(f'Authored {len(LESSONS)} lessons, {sum(len(l["points"]) for l in LESSONS)} units, {len(pool)} examples, {sum(len(l["questions"]) for l in LESSONS)} questions.')

if __name__ == '__main__':
    build()
